          this.load();
          this.loadStats();
        },
        error: err => {
          this.saving = false;
          console.error('Erreur mise à jour:', err);
          const msg = err.error ? JSON.stringify(err.error) : 'Erreur lors de la mise à jour';
          alert(msg);
        }
      });
